//! 📐️ Original CAD variant fields remain in one snapshot and scalar row workspace.
use super::{SemioCadSnapshot,CadLayer,CadBlock,CadEntityRecord,CadEntity,SemioPoint2,identity,boolean,optional_integer,float_columns,point};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioCadSnapshot>,validation:SchemaValidationStorage,indices:[RowIndexStorage;13],orders:[Vec<usize>;4],unique:[Vec<usize>;2],record_unique:Vec<Vec<usize>>}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),indices:std::array::from_fn(|_|RowIndexStorage::empty()),orders:std::array::from_fn(|_|Vec::new()),unique:std::array::from_fn(|_|Vec::new()),record_unique:Vec::new()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
struct Rows<'a>{entities:RowIndex<'a>,order:&'a[usize],lines:RowIndex<'a>,arcs:RowIndex<'a>,circles:RowIndex<'a>,ellipses:RowIndex<'a>,polylines:RowIndex<'a>,texts:RowIndex<'a>,inserts:RowIndex<'a>,solids:RowIndex<'a>,dimensions:RowIndex<'a>,vertices:RowIndex<'a>,vertex_order:&'a[usize]}
impl Rows<'_>{
fn records_into(&mut self,records:&mut Vec<CadEntityRecord>,unique:&mut Vec<usize>,owner:Option<i64>,layers:&RowIndex<'_>,blocks:&RowIndex<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
let range=self.entities.range_by(self.order,(0,owner),control,|row|Ok((0,optional_integer(row,2)?)))?;self.entities.unique_text(unique,&self.order[range.clone()],4,control,"duplicate Semio CAD entity handle within owner")?;*records=reserve(range.len(),control)?;
for ordinal in range{let row=self.entities.take_index(self.order[ordinal],control)?.ok_or_else(||invalid("duplicate Semio CAD entity ownership"))?;records.push(CadEntityRecord{handle:String::new(),layer:String::new(),entity:CadEntity::Line{a:SemioPoint2::default(),b:SemioPoint2::default()}});let record=records.last_mut().unwrap();
match row.text(6)?{
"line"=>{let detail=self.lines.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD line fields"))?;record.entity=CadEntity::Line{a:point(detail,1)?,b:point(detail,3)?};},
"arc"=>{let detail=self.arcs.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD arc fields"))?;record.entity=CadEntity::Arc{center:point(detail,1)?,radius:detail.real(3)?,start_angle:detail.real(4)?,end_angle:detail.real(5)?};},
"circle"=>{let detail=self.circles.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD circle fields"))?;record.entity=CadEntity::Circle{center:point(detail,1)?,radius:detail.real(3)?};},
"ellipse"=>{let detail=self.ellipses.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD ellipse fields"))?;record.entity=CadEntity::Ellipse{center:point(detail,1)?,major_axis_end:point(detail,3)?,ratio:detail.real(5)?,start_param:detail.real(6)?,end_param:detail.real(7)?};},
"polyline"=>{let detail=self.polylines.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD polyline fields"))?;let range=self.vertices.range_by(self.vertex_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;record.entity=CadEntity::Polyline{vertices:Vec::new(),closed:boolean(detail.integer(1)?)?};let CadEntity::Polyline{vertices,..}=&mut record.entity else{unreachable!()};*vertices=reserve(range.len(),control)?;for ordinal in range{let vertex=self.vertices.take_index(self.vertex_order[ordinal],control)?.ok_or_else(||invalid("duplicate CAD vertex ownership"))?;vertices.push(point(vertex,3)?);control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,vertices.len(),0)?;}},
"text"=>{let detail=self.texts.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD text fields"))?;record.entity=CadEntity::Text{position:point(detail,1)?,height:detail.real(3)?,rotation:detail.real(4)?,content:String::new()};let CadEntity::Text{content,..}=&mut record.entity else{unreachable!()};reconstruct_text_into(content,control,detail.text(5)?)?;},
"insert"=>{let detail=self.inserts.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD insert fields"))?;let block=blocks.get(detail.integer(1)?,control)?.ok_or_else(||invalid("dangling CAD inserted block"))?;record.entity=CadEntity::Insert{block_name:String::new(),insertion_point:point(detail,2)?,scale:point(detail,4)?,rotation:detail.real(6)?};let CadEntity::Insert{block_name,..}=&mut record.entity else{unreachable!()};reconstruct_text_into(block_name,control,block.text(3)?)?;},
"solid"=>{let detail=self.solids.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD solid fields"))?;record.entity=CadEntity::Solid{p1:point(detail,1)?,p2:point(detail,3)?,p3:point(detail,5)?,p4:point(detail,7)?};},
"dimension"=>{let detail=self.dimensions.take(row.rowid,control)?.ok_or_else(||invalid("missing CAD dimension fields"))?;record.entity=CadEntity::Dimension{def_point:point(detail,1)?,text_position:point(detail,3)?,measurement:detail.real(5)?,text:String::new()};let CadEntity::Dimension{text,..}=&mut record.entity else{unreachable!()};reconstruct_text_into(text,control,detail.text(6)?)?;},
_=>return Err(invalid("unknown Semio CAD entity kind"))
}
reconstruct_text_into(&mut record.handle,control,row.text(4)?)?;let layer=layers.get(row.integer(5)?,control)?.ok_or_else(||invalid("dangling CAD entity layer"))?;reconstruct_text_into(&mut record.layer,control,layer.text(3)?)?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,records.len(),self.entities.len())?;
}Ok(())
}
}
/// 🪢️ Borrows the source into one admitted original CAD prefix before semantic validation or heap birth.
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioCadSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioCadSnapshot::SQLITE_SCHEMA,phase,control)?;let document=super::single_float_row(database,"semio_cad_document")?;identity(document,2)?;if document.rowid!=1{return Err(invalid("invalid Semio CAD document identifier"))}
let [layer_s,block_s,line_s,arc_s,circle_s,ellipse_s,polyline_s,text_s,insert_s,solid_s,dimension_s,vertex_s,entity_s]=&mut prefix.indices;let layers=RowIndex::new(layer_s,database,"semio_cad_layer",7,&[],control,"invalid CAD layer identity")?;let blocks=RowIndex::new(block_s,database,"semio_cad_block",6,float_columns("semio_cad_block"),control,"invalid CAD block identity")?;let lines=RowIndex::new(line_s,database,"semio_cad_line",5,float_columns("semio_cad_line"),control,"invalid CAD line identity")?;let arcs=RowIndex::new(arc_s,database,"semio_cad_arc",6,float_columns("semio_cad_arc"),control,"invalid CAD arc identity")?;let circles=RowIndex::new(circle_s,database,"semio_cad_circle",4,float_columns("semio_cad_circle"),control,"invalid CAD circle identity")?;let ellipses=RowIndex::new(ellipse_s,database,"semio_cad_ellipse",8,float_columns("semio_cad_ellipse"),control,"invalid CAD ellipse identity")?;let polylines=RowIndex::new(polyline_s,database,"semio_cad_polyline",2,&[],control,"invalid CAD polyline identity")?;let texts=RowIndex::new(text_s,database,"semio_cad_text",6,float_columns("semio_cad_text"),control,"invalid CAD text identity")?;let inserts=RowIndex::new(insert_s,database,"semio_cad_insert",7,float_columns("semio_cad_insert"),control,"invalid CAD insert identity")?;let solids=RowIndex::new(solid_s,database,"semio_cad_solid",9,float_columns("semio_cad_solid"),control,"invalid CAD solid identity")?;let dimensions=RowIndex::new(dimension_s,database,"semio_cad_dimension",7,float_columns("semio_cad_dimension"),control,"invalid CAD dimension identity")?;let vertices=RowIndex::new(vertex_s,database,"semio_cad_polyline_vertex",5,float_columns("semio_cad_polyline_vertex"),control,"invalid CAD vertex identity")?;let entities=RowIndex::new(entity_s,database,"semio_cad_entity",7,&[],control,"invalid CAD entity identity")?;
let [layer_order,block_order,vertex_order,entity_order]=&mut prefix.orders;layers.ordered_into(layer_order,2,control,"Semio CAD layer ordinals")?;blocks.ordered_into(block_order,2,control,"Semio CAD block ordinals")?;let [layer_unique,block_unique]=&mut prefix.unique;for(rows,scratch)in [(&layers,layer_unique),(&blocks,block_unique)]{rows.unique_text(scratch,rows.indices(),3,control,"duplicate Semio CAD native identity")?;for &index in rows.indices(){if rows.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio CAD native ownership"))}control.checkpoint(phase,index,rows.len())?;}}
for &index in vertices.indices(){if polylines.get(vertices.row(index)?.integer(1)?,control)?.is_none(){return Err(invalid("invalid CAD polyline vertex owner"))}control.checkpoint(phase,index,vertices.len())?;}vertices.grouped_by_into(vertex_order,2,control,"Semio CAD vertex ordinals",|row|Ok((0,Some(row.integer(1)?))))?;for &index in entities.indices(){let row=entities.row(index)?;if row.integer(1)?!=1{return Err(invalid("invalid CAD entity ownership"))}if let Some(id)=optional_integer(row,2)?{if blocks.get(id,control)?.is_none(){return Err(invalid("invalid CAD entity ownership"))}}control.checkpoint(phase,index,entities.len())?;}entities.grouped_by_into(entity_order,3,control,"Semio CAD entity ordinals",|row|Ok((0,optional_integer(row,2)?)))?;
let mut rows=Rows{entities,order:entity_order,lines,arcs,circles,ellipses,polylines,texts,inserts,solids,dimensions,vertices,vertex_order};let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.layers=reserve(layer_order.len(),control)?;snapshot.blocks=reserve(block_order.len(),control)?;prefix.record_unique=reserve(block_order.len().checked_add(1).ok_or_else(||invalid("CAD owner extent overflow"))?,control)?;
for &index in layer_order.iter(){let row=layers.row(index)?;snapshot.layers.push(CadLayer{name:String::new(),color_index:i32::try_from(row.integer(4)?).map_err(|_|invalid("CAD color index exceeds signed word"))?,line_type:String::new(),visible:boolean(row.integer(6)?)?});let layer=snapshot.layers.last_mut().unwrap();reconstruct_text_into(&mut layer.name,control,row.text(3)?)?;reconstruct_text_into(&mut layer.line_type,control,row.text(5)?)?;}
prefix.record_unique.push(Vec::new());rows.records_into(&mut snapshot.entities,prefix.record_unique.last_mut().unwrap(),None,&layers,&blocks,control)?;for &index in block_order.iter(){let row=blocks.row(index)?;snapshot.blocks.push(CadBlock{name:String::new(),base_point:point(row,4)?,entities:Vec::new()});prefix.record_unique.push(Vec::new());let block=snapshot.blocks.last_mut().unwrap();reconstruct_text_into(&mut block.name,control,row.text(3)?)?;rows.records_into(&mut block.entities,prefix.record_unique.last_mut().unwrap(),Some(row.rowid),&layers,&blocks,control)?;}
if [rows.entities.remaining(),rows.lines.remaining(),rows.arcs.remaining(),rows.circles.remaining(),rows.ellipses.remaining(),rows.polylines.remaining(),rows.texts.remaining(),rows.inserts.remaining(),rows.solids.remaining(),rows.dimensions.remaining(),rows.vertices.remaining()].iter().any(|count|*count!=0){return Err(invalid("orphan or contradictory Semio CAD variant detail"))}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,1,1)
},|prefix|prefix.snapshot.take().unwrap())}
                                                             